; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; MAGIC: casting and the spells (5D83-62FD).
;
; The Cast command and the 32 spells. CastSpell (5D83, called by the Cast command at LOOP 1D60
; and by the combat Cast at COMBAT 8D51 with BX = the caster's record) picks the menu by the
; class: Cleric, Paladin, Illusionist cast cleric spells, Wizard, Lark, Alchemist wizard
; spells, Druid and Ranger choose W or C, the others are "Not a mage!". A spell letter A-P
; costs 5 x its index magic points (A 0 ... P 75, BCD); the name is printed from SpellNames
; and the handler is jumped to through WizardSpellCmds or ClericSpellCmds (both in ITEMS).
; Each handler ends with a jump to Cast_Done (StatusLine, ret) or Cast_Failed ("Failed!").
; Handlers get BX = caster's record, DL = the spell's index (SpellFlash's pitch).
; Helpers: SpellFlash (sound and flash), HitAllMonsters (5EAA), HealPlayer (5F0A),
; CastDirected (5F2D), DungeonTeleport (5F7B).
; In a fight (Location 80h) the combat data lives in the start-up area (docs/FORMATS.md 9):
; StartUp+80h/+88h = the 8 monsters' x/y, +98h their hit points, +0A0h/+0A4h the four
; fighters' x/y; CombatPlayer = the fighter whose turn it is, FoeTile = the monsters' shape, KillSpellUsed =
; Repond/Pontori already tried this fight.
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN PutChar:NEAR
EXTRN Random:NEAR
EXTRN DrawView:NEAR
EXTRN ViewTileAt:NEAR
EXTRN Sound:NEAR
EXTRN Ofs80h:BYTE
EXTRN CmbMonY:BYTE
EXTRN CmbMonHP:BYTE
EXTRN Location:BYTE
EXTRN Players:BYTE
EXTRN PlrInt:BYTE
EXTRN PlayerXY:BYTE
EXTRN LightOn:BYTE
EXTRN DungeonLevel:BYTE
EXTRN TimeStop:BYTE
EXTRN StartUp:NEAR
EXTRN ShowGemMap:NEAR
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN MapCellAddr:NEAR
EXTRN DungeonCell:NEAR
EXTRN ShowDungeonMap:NEAR
EXTRN SpellNames:BYTE
EXTRN WizardSpellCmds:BYTE
EXTRN ClericSpellCmds:BYTE
EXTRN MsgNotAMage:BYTE
EXTRN MsgSpellType:BYTE
EXTRN MsgClericSpell:BYTE
EXTRN MsgWizardSpell:BYTE
EXTRN MsgMPTooLow:BYTE
EXTRN MsgFailed:BYTE
EXTRN MsgHealWhom:BYTE
EXTRN MsgCureWhom:BYTE
EXTRN MsgResurectWhom:BYTE
EXTRN MsgRecallWhom:BYTE
EXTRN MsgSpellDirect:BYTE
EXTRN ReadKeyUpper:NEAR
EXTRN AddHitPoints:NEAR
EXTRN ExitToSosaria:NEAR
EXTRN AskPlayer:NEAR
EXTRN StatusLine:NEAR
EXTRN FlashPlayer:NEAR
EXTRN FlashView:NEAR
EXTRN CheckTerrain:NEAR
EXTRN TxtNotHere:BYTE
EXTRN AskDirection:NEAR
EXTRN ChestLoot:NEAR
EXTRN CombatPlayer:BYTE
EXTRN FoeTile:BYTE
EXTRN KillSpellUsed:BYTE
EXTRN ShootLine:NEAR
EXTRN DamageFoe:NEAR
PUBLIC CastSpell
PUBLIC SpellRepond
PUBLIC SpellMittar
PUBLIC SpellLorum
PUBLIC SpellDorAcron
PUBLIC SpellSurAcron
PUBLIC SpellFulgar
PUBLIC SpellDagAcron
PUBLIC SpellMentar
PUBLIC SpellDagLorum
PUBLIC SpellFalDivi
PUBLIC SpellNoxum
PUBLIC SpellDecorp
PUBLIC SpellAltair
PUBLIC SpellDagMentar
PUBLIC SpellNecorp
PUBLIC SpellZxkuqyb
PUBLIC SpellPontori
PUBLIC SpellApparUnem
PUBLIC SpellSanctu
PUBLIC SpellLibRec
PUBLIC SpellAlcort
PUBLIC SpellSequitu
PUBLIC SpellSanctuMani
PUBLIC SpellVieda
PUBLIC SpellSurmandum
PUBLIC SpellAnjuSermani
;------------------------------------------------------------------------------
; CastSpell: the Cast command. In: BX = the caster's record. Chooses the spell list by class
; (asks "Spell type W/C-" for a druid or ranger), reads A-P (Esc leaves), checks and takes
; the magic points, prints the spell's name and jumps to its handler, which returns to the
; caller through Cast_Done. DI = handler table, SI = menu prompt, DH = 0 wizard / 10h cleric
; (offset into SpellNames).
;------------------------------------------------------------------------------
CastSpell:	mov al, byte ptr [bx+17h]	; class	;@5D83
	cmp al, 44h	; 'D' druid	;@5D86
	je Cast_AskType	;@5D88
	cmp al, 52h	; 'R' ranger	;@5D8A
	je Cast_AskType	;@5D8C
	lea di, ClericSpellCmds	;@5D8E
	lea si, MsgClericSpell	;@5D92
	mov dh, 10h	;@5D96
	cmp al, 43h	; 'C' cleric	;@5D98
	je Cast_Menu	;@5D9A
	cmp al, 50h	; 'P' paladin	;@5D9C
	je Cast_Menu	;@5D9E
	cmp al, 49h	; 'I' illusionist	;@5DA0
	je Cast_Menu	;@5DA2
	lea di, WizardSpellCmds	;@5DA4
	lea si, MsgWizardSpell	;@5DA8
	mov dh, 0	;@5DAC
	cmp al, 57h	; 'W' wizard	;@5DAE
	je Cast_Menu	;@5DB0
	cmp al, 4Ch	; 'L' lark	;@5DB2
	je Cast_Menu	;@5DB4
	cmp al, 41h	; 'A' alchemist	;@5DB6
	je Cast_Menu	;@5DB8
	lea si, MsgNotAMage	;@5DBA
	call PrintMsg	;@5DBE
	mov al, 0FFh	; sound 0FFh: the error beep	;@5DC1
	call Sound	;@5DC3
	jmp Cast_Done	;@5DC6
Cast_AskType:	lea si, MsgSpellType	;@5DC9
	call PrintMsg	;@5DCD
Cast_TypeKey:	call ReadKeyUpper	; AL = key, AH = upper case	;@5DD0
	lea di, WizardSpellCmds	;@5DD3
	lea si, MsgWizardSpell	;@5DD7
	mov dh, 0	;@5DDB
	cmp ah, 57h	; 'W'	;@5DDD
	je Cast_EchoType	;@5DE0
	lea di, ClericSpellCmds	;@5DE2
	lea si, MsgClericSpell	;@5DE6
	mov dh, 10h	;@5DEA
	cmp ah, 43h	; 'C'	;@5DEC
	je Cast_EchoType	;@5DEF
	cmp al, 1Bh	; Esc	;@5DF1
	je Cast_Esc	;@5DF3
	mov al, 0FFh	;@5DF5
	call Sound	;@5DF7
	jmp Cast_TypeKey	;@5DFA
Cast_EchoType:	call PutChar	;@5DFC
Cast_Menu:	call PrintMsg	;@5DFF
Cast_SpellKey:	call ReadKeyUpper	;@5E02
	cmp al, 1Bh	; Esc	;@5E05
	je Cast_Esc	;@5E07
	cmp ah, 41h	; 'A'	;@5E09
	jb Cast_BadKey	;@5E0C
	cmp ah, 50h	; 'P'	;@5E0E
	ja Cast_BadKey	;@5E11
	call PutChar	;@5E13
	call ScrollMsg	;@5E16
	sub ah, 41h	; AH = spell index 0-15	;@5E19
	jmp short Cast_Spell	;@5E1C
Cast_BadKey:	mov al, 0FFh	;@5E1E
	call Sound	;@5E20
	jmp Cast_SpellKey	;@5E23
Cast_Spell:	mov al, ah	;@5E25
	mov dl, al	; DL = spell index	;@5E27
	mov ah, 5	;@5E29
	mul ah	; AX = index x 5	;@5E2B
	aam	; to BCD: AH tens, AL units	;@5E2D
	mov cl, 4	;@5E2F
	shl ah, cl	;@5E31
	or al, ah	;@5E33
	cmp al, byte ptr [bx+19h]	; magic points (BCD)	;@5E35
	ja Cast_MPLow	;@5E38
	xchg byte ptr [bx+19h], al	; magic points -= cost	;@5E3A
	sub al, byte ptr [bx+19h]	;@5E3D
	das	;@5E40
	mov byte ptr [bx+19h], al	;@5E41
	call ScrollMsg	;@5E44
	mov al, dl	;@5E47
	add al, dh	;@5E49
	mov ah, 0	;@5E4B
	mov si, ax	;@5E4D
	shl si, 1	;@5E4F
	mov al, dl	;@5E51
	shl al, 1	;@5E53
	add di, ax	;@5E55
	mov si, word ptr SpellNames[si]	; the spell's name	;@5E57
	call PrintMsg	;@5E5B
	call ScrollMsg	;@5E5E
	call ScrollMsg	;@5E61
	jmp word ptr [di]	; to the handler	;@5E64
Cast_Esc:	call ScrollMsg	;@5E66
Cast_Done:	call StatusLine	; every spell ends here	;@5E69
	ret	;@5E6C
Cast_MPLow:	lea si, MsgMPTooLow	;@5E6D
	call PrintMsg	;@5E71
	mov al, 0FFh	;@5E74
	call Sound	;@5E76
	jmp Cast_Done	;@5E79
; Cast_Failed: "Failed!", the failure sound, then Cast_Done. The shared exit of the spells.
Cast_Failed:	lea si, MsgFailed	;@5E7B
	call PrintMsg	;@5E7F
	mov al, 0FAh	; sound 0FAh: failure	;@5E82
	call Sound	;@5E84
	jmp Cast_Done	;@5E87
;------------------------------------------------------------------------------
; SpellFlash: the sound and flash of a spell that works: sound 0F5h, FlashView, a tone
; with pitch from DL (the spell's index), FlashView. Uses: nothing (saves all).
;------------------------------------------------------------------------------
SpellFlash:	pushf	;@5E89
	push ax	;@5E8A
	push bx	;@5E8B
	mov al, 0F5h	;@5E8C
	call Sound	;@5E8E
	call FlashView	; FlashView	;@5E91
	mov al, 0FDh	; sound 0FDh, BH, BL = parameters (?)	;@5E94
	mov bh, 30h	;@5E96
	mov bl, dl	;@5E98
	and bl, 0Fh	;@5E9A
	or bl, 60h	;@5E9D
	call Sound	;@5EA0
	call FlashView	; FlashView	;@5EA3
	pop bx	;@5EA6
	pop ax	;@5EA7
	popf	;@5EA8
	ret	;@5EA9
;------------------------------------------------------------------------------
; HitAllMonsters: each of the 8 monsters that is alive is hit with a chance of 3 in 4: its
; cell flashes the magic shape (3Ch, shape 60) and DamageFoe deals AL damage (0FFh: kills).
; In: AL = damage. Uses: nothing (saves all). Callers: Repond, Noxum, Dag Mentar, Zxkuqyb,
; Pontori.
;------------------------------------------------------------------------------
HitAllMonsters:	pushf	;@5EAA
	push ax	;@5EAB
	push bx	;@5EAC
	push cx	;@5EAD
	push dx	;@5EAE
	push si	;@5EAF
	push di	;@5EB0
	mov si, ax	; SI = damage	;@5EB1
	mov al, byte ptr CombatPlayer	; the caster's slot in the party	;@5EB3
	mov ah, 40h	;@5EB6
	mul ah	;@5EB8
	mov di, ax	;@5EBA
	lea di, Players[di]	; DI = the caster's record	;@5EBC
	mov cx, 8	; 8 monster slots	;@5EC0
	lea bx, StartUp	; BX walks the monster arrays (StartUp+n)	;@5EC3
HitAll_Loop:	mov dh, 0FFh	;@5EC7
	call Random	;@5EC9
	and dl, 3	; 1 in 4: this one is spared	;@5ECC
	je HitAll_Next	;@5ECF
	cmp byte ptr CmbMonHP[bx], 0	; monster hit points: 0 = none	;@5ED1
	je HitAll_Next	;@5ED6
	mov dh, byte ptr CmbMonY[bx]	; its y	;@5ED8
	mov dl, byte ptr Ofs80h[bx]	; its x	;@5EDC
	xchg bx, dx	;@5EE0
	call ViewTileAt	; BX = its cell in the view buffer	;@5EE2
	mov byte ptr [bx], 3Ch	; shape 60: magic	;@5EE5
	call DrawView	;@5EE8
	mov al, 0F7h	; sound 0F7h: a hit	;@5EEB
	call Sound	;@5EED
	mov al, byte ptr FoeTile	; the monster's shape back	;@5EF0
	mov byte ptr [bx], al	;@5EF3
	call DrawView	;@5EF5
	xchg bx, dx	;@5EF8
	mov ax, si	;@5EFA
	call DamageFoe	; damage the monster BX by AX (?)	;@5EFC
HitAll_Next:	inc bx	;@5EFF
	loop HitAll_Loop	;@5F00
	pop di	;@5F02
	pop si	;@5F03
	pop dx	;@5F04
	pop cx	;@5F05
	pop bx	;@5F06
	pop ax	;@5F07
	popf	;@5F08
	ret	;@5F09
;------------------------------------------------------------------------------
; HealPlayer: "Heal whom?", then add DH (BCD) hit points to that player (at most the
; maximum) and flash its status. In: DH = amount. Callers: Sanctu Mani.
;------------------------------------------------------------------------------
HealPlayer:	lea si, MsgHealWhom	;@5F0A
	call PrintMsg	;@5F0E
	call AskPlayer	; AL = 1-4, BX = record; ZF on Esc	;@5F11
	je HealPlayer_Done	;@5F14
	dec al	;@5F16
	mov cl, al	;@5F18
	mov al, dh	;@5F1A
	call AddHitPoints	;@5F1C
	mov al, cl	;@5F1F
	call FlashPlayer	; FlashPlayer	;@5F21
	call SpellFlash	;@5F24
	call FlashPlayer	; FlashPlayer	;@5F27
HealPlayer_Done:	jmp Cast_Done	;@5F2A
;------------------------------------------------------------------------------
; CastDirected: in a fight, "Direct? " and AL damage (0FFh: kills) to the first monster in
; that direction from the caster; elsewhere, or a miss, "Failed!". Esc: nothing (the magic
; points are gone). In: AL = damage. Callers: Mittar, Fulgar, Mentar, Decorp.
;------------------------------------------------------------------------------
CastDirected:	mov di, ax	; DI = damage	;@5F2D
	cmp byte ptr Location, 80h	; 80h: a fight	;@5F2F
	jne CastDir_Fail	;@5F34
	lea si, MsgSpellDirect	;@5F36
	call PrintMsg	;@5F3A
	call AskDirection	; ask a direction: DX = step, ZF on Esc (?)	;@5F3D
	je CastDir_Done	;@5F40
	call SpellFlash	;@5F42
	mov cx, dx	; CX = the step	;@5F45
	mov bl, byte ptr CombatPlayer	;@5F47
	mov bh, 0	;@5F4B
	mov dh, byte ptr StartUp+0A4h[bx]	; the caster's y in the fight	;@5F4D
	mov dl, byte ptr StartUp+0A0h[bx]	; its x	;@5F51
	call ShootLine	; BX = the monster hit, or -1 (?)	;@5F55
	cmp bx, -1	;@5F58
	je CastDir_Fail	;@5F5B
	mov al, 0F7h	; sound 0F7h	;@5F5D
	call Sound	;@5F5F
	mov al, byte ptr CombatPlayer	;@5F62
	mov ah, 40h	;@5F65
	mul ah	;@5F67
	xchg di, ax	; AX = damage, DI = offset of the record	;@5F69
	lea di, Players[di]	;@5F6A
	lea bx, StartUp[bx]	;@5F6E
	call DamageFoe	; damage the monster BX by AX (?)	;@5F72
CastDir_Done:	jmp Cast_Done	;@5F75
CastDir_Fail:	jmp Cast_Failed	;@5F78
;------------------------------------------------------------------------------
; DungeonTeleport: put the party on a random empty cell (0) of the dungeon level.
; Uses: nothing (saves all). Callers: Dor Acron, Sur Acron, Lib Rec.
;------------------------------------------------------------------------------
DungeonTeleport:	pushf	;@5F7B
	push ax	;@5F7C
	push bx	;@5F7D
	push cx	;@5F7E
	push dx	;@5F7F
	mov dh, 10h	; x, y 0-15	;@5F80
DunTele_Try:	call Random	;@5F82
	mov cl, dl	;@5F85
	call Random	;@5F87
	mov ch, dl	;@5F8A
	mov bx, cx	;@5F8C
	call DungeonCell	;@5F8E
	cmp al, 0	; 0: an empty cell	;@5F91
	jne DunTele_Try	;@5F93
	mov word ptr PlayerXY, cx	;@5F95
	pop dx	;@5F99
	pop cx	;@5F9A
	pop bx	;@5F9B
	pop ax	;@5F9C
	popf	;@5F9D
	ret	;@5F9E
;------------------------------------------------------------------------------
; SpellRepond (wizard A): only in a fight against orcs (shape 18h), once a fight (KillSpellUsed),
; and then only one time in two: HitAllMonsters with 0FFh (each orc dies 3 in 4).
;------------------------------------------------------------------------------
SpellRepond:	cmp byte ptr Location, 80h	;@5F9F
	jne Repond_Fail	;@5FA4
	cmp byte ptr FoeTile, 18h	; the monsters' shape: 24 orc	;@5FA6
	jne Repond_Fail	;@5FAB
	cmp byte ptr KillSpellUsed, 0	; tried already this fight?	;@5FAD
	jne Repond_Fail	;@5FB2
	mov byte ptr KillSpellUsed, 0FFh	;@5FB4
	mov al, dl	; keep the spell index	;@5FB9
	mov dh, 0FFh	;@5FBB
	call Random	;@5FBD
	shl dl, 1	; bit 7: 1 in 2	;@5FC0
	jb Repond_Fail	;@5FC2
	mov dl, al	;@5FC4
	call SpellFlash	;@5FC6
	mov al, 0FFh	;@5FC9
	call HitAllMonsters	;@5FCB
	jmp Cast_Done	;@5FCE
Repond_Fail:	jmp Cast_Failed	;@5FD1
;------------------------------------------------------------------------------
; SpellMittar (wizard B): directed damage 16-55 (random 0-39, bit 4 set).
;------------------------------------------------------------------------------
SpellMittar:	mov al, dl	;@5FD4
	mov dh, 28h	;@5FD6
	call Random	;@5FD8
	or dl, 10h	;@5FDB
	xchg al, dl	;@5FDE
	jmp CastDirected	;@5FE0
;------------------------------------------------------------------------------
; SpellLorum (wizard C, cleric D Luminae): light for 10 moves.
;------------------------------------------------------------------------------
SpellLorum:	mov byte ptr LightOn, 0Ah	;@5FE3
	call SpellFlash	;@5FE8
	jmp Cast_Done	;@5FEB
;------------------------------------------------------------------------------
; SpellDorAcron (wizard D, cleric F Rec Du): in a dungeon, one level down (not below the
; eighth, level 7) to a random empty cell.
;------------------------------------------------------------------------------
SpellDorAcron:	cmp byte ptr Location, 1	; 1: a dungeon	;@5FEE
	jne DorAcron_Fail	;@5FF3
	call SpellFlash	;@5FF5
	cmp byte ptr DungeonLevel, 7	;@5FF8
	jae DorAcron_Fail	;@5FFD
	inc byte ptr DungeonLevel	;@5FFF
	call DungeonTeleport	;@6003
	jmp Cast_Done	;@6006
DorAcron_Fail:	jmp Cast_Failed	;@6009
;------------------------------------------------------------------------------
; SpellSurAcron (wizard E, cleric E Rec Su): in a dungeon, one level up to a random empty
; cell; from the first level out to Sosaria (ExitToSosaria).
;------------------------------------------------------------------------------
SpellSurAcron:	cmp byte ptr Location, 1	;@600C
	jne SurAcron_Fail	;@6011
	call SpellFlash	;@6013
	cmp byte ptr DungeonLevel, 0	;@6016
	je SurAcron_Exit	;@601B
	dec byte ptr DungeonLevel	;@601D
	call DungeonTeleport	;@6021
SurAcron_Done:	jmp Cast_Done	;@6024
SurAcron_Fail:	jmp Cast_Failed	;@6027
SurAcron_Exit:	call ExitToSosaria	;@602A
	jmp SurAcron_Done	;@602D
;------------------------------------------------------------------------------
; SpellFulgar (wizard F): directed damage 75 (4Bh).
;------------------------------------------------------------------------------
SpellFulgar:	mov al, 4Bh	;@602F
	jmp CastDirected	;@6031
;------------------------------------------------------------------------------
; SpellDagAcron (wizard G): in Sosaria only, teleport to a random place the party may stand
; on (not a whirlpool 30h, force field 80h or lava 84h, and CheckTerrain must pass). Probably
; a bug: CheckTerrain (PARTY 7254) wants a shape number, but gets the map byte (shape x 4),
; so on foot only brush (08h) seems to pass (?).
;------------------------------------------------------------------------------
SpellDagAcron:	cmp byte ptr Location, 0	; 0: Sosaria	;@6034
	jne DagAcron_Fail	;@6039
	call SpellFlash	;@603B
DagAcron_Try:	mov dh, 40h	; x, y 0-63	;@603E
	call Random	;@6040
	mov bl, dl	;@6043
	call Random	;@6045
	mov bh, dl	;@6048
	mov cx, bx	;@604A
	call MapCellAddr	;@604C
	cmp al, 30h	; map byte 30h: whirlpool	;@604F
	je DagAcron_Try	;@6051
	cmp al, 80h	; 80h: force field	;@6053
	je DagAcron_Try	;@6055
	cmp al, 84h	; 84h: lava	;@6057
	je DagAcron_Try	;@6059
	call CheckTerrain	; CheckTerrain: ZF = may stand there	;@605B
	jne DagAcron_Try	;@605E
	mov word ptr PlayerXY, cx	;@6060
	jmp Cast_Done	;@6064
DagAcron_Fail:	jmp Cast_Failed	;@6067
;------------------------------------------------------------------------------
; SpellMentar (wizard H): directed damage 2 x the caster's intelligence.
;------------------------------------------------------------------------------
SpellMentar:	mov al, byte ptr CombatPlayer	;@606A
	mov ah, 40h	;@606D
	mul ah	;@606F
	mov bx, ax	;@6071
	mov al, byte ptr PlrInt[bx]	; PlrInt = Players+14h: intelligence (BCD)	;@6073
	mov ah, 0	;@6077
	mov cl, 4	;@6079
	shl ax, cl	;@607B
	mov al, byte ptr PlrInt[bx]	;@607D
	and al, 0Fh	;@6081
	aad	; AL = intelligence in binary	;@6083
	shl al, 1	;@6085
	jmp CastDirected	;@6087
;------------------------------------------------------------------------------
; SpellDagLorum (wizard I, cleric J Sominae): light for 250 moves.
;------------------------------------------------------------------------------
SpellDagLorum:	mov byte ptr LightOn, 0FAh	;@608A
	call SpellFlash	;@608F
	jmp Cast_Done	;@6092
;------------------------------------------------------------------------------
; SpellFalDivi (wizard J): cast a cleric spell: back to the cleric menu (that spell's magic
; points are taken too).
;------------------------------------------------------------------------------
SpellFalDivi:	call SpellFlash	;@6095
	lea di, ClericSpellCmds	;@6098
	lea si, MsgClericSpell	;@609C
	mov dh, 10h	;@60A0
	jmp Cast_Menu	;@60A2
;------------------------------------------------------------------------------
; SpellNoxum (wizard K): in a fight, 75 damage to every monster (each 3 in 4).
;------------------------------------------------------------------------------
SpellNoxum:	cmp byte ptr Location, 80h	;@60A5
	jne Noxum_Fail	;@60AA
	call SpellFlash	;@60AC
	mov al, 4Bh	;@60AF
	call HitAllMonsters	;@60B1
	jmp Cast_Done	;@60B4
Noxum_Fail:	jmp Cast_Failed	;@60B7
;------------------------------------------------------------------------------
; SpellDecorp (wizard L, cleric M Excuun): kill the monster in a direction.
;------------------------------------------------------------------------------
SpellDecorp:	mov al, 0FFh	;@60BA
	jmp CastDirected	;@60BC
;------------------------------------------------------------------------------
; SpellAltair (wizard M): stop time (TimeStop = 10), as the Negate command.
;------------------------------------------------------------------------------
SpellAltair:	mov byte ptr TimeStop, 0Ah	;@60BF
	call SpellFlash	;@60C4
	jmp Cast_Done	;@60C7
;------------------------------------------------------------------------------
; SpellDagMentar (wizard N): in a fight, 2 x intelligence damage to every monster (each
; 3 in 4).
;------------------------------------------------------------------------------
SpellDagMentar:	cmp byte ptr Location, 80h	;@60CA
	jne DagMentar_Fail	;@60CF
	call SpellFlash	;@60D1
	mov al, byte ptr CombatPlayer	;@60D4
	mov ah, 40h	;@60D7
	mul ah	;@60D9
	mov bx, ax	;@60DB
	mov al, byte ptr PlrInt[bx]	; intelligence (BCD)	;@60DD
	mov ah, 0	;@60E1
	mov cl, 4	;@60E3
	shl ax, cl	;@60E5
	mov al, byte ptr PlrInt[bx]	;@60E7
	and al, 0Fh	;@60EB
	aad	;@60ED
	shl al, 1	;@60EF
	call HitAllMonsters	;@60F1
	jmp Cast_Done	;@60F4
DagMentar_Fail:	jmp Cast_Failed	;@60F7
;------------------------------------------------------------------------------
; SpellNecorp (wizard O): in a fight, every living monster's hit points become 5.
;------------------------------------------------------------------------------
SpellNecorp:	cmp byte ptr Location, 80h	;@60FA
	jne Necorp_Fail	;@60FF
	call SpellFlash	;@6101
	mov cx, 8	;@6104
	lea si, StartUp	;@6107
Necorp_Loop:	cmp byte ptr CmbMonHP[si], 0	; monster hit points	;@610B
	je Necorp_Next	;@6110
	mov byte ptr CmbMonHP[si], 5	; 5 left	;@6112
	mov bh, byte ptr CmbMonY[si]	;@6117
	mov bl, byte ptr Ofs80h[si]	;@611B
	call ViewTileAt	; BX = its view cell	;@611F
	mov byte ptr [bx], 3Ch	; shape 60: magic	;@6122
	call DrawView	;@6125
	mov al, 0F7h	;@6128
	call Sound	;@612A
	mov al, byte ptr FoeTile	; the monster's shape back	;@612D
	mov byte ptr [bx], al	;@6130
	call DrawView	;@6132
Necorp_Next:	inc si	;@6135
	loop Necorp_Loop	;@6136
	jmp Cast_Done	;@6138
Necorp_Fail:	jmp Cast_Failed	;@613B
;------------------------------------------------------------------------------
; SpellZxkuqyb (cleric O, and the nameless wizard spell P): in a fight, kill every monster
; (each 3 in 4).
;------------------------------------------------------------------------------
SpellZxkuqyb:	cmp byte ptr Location, 80h	;@613E
	jne Zxkuqyb_Fail	;@6143
	call SpellFlash	;@6145
	mov al, 0FFh	;@6148
	call HitAllMonsters	;@614A
	jmp Cast_Done	;@614D
Zxkuqyb_Fail:	jmp Cast_Failed	;@6150
;------------------------------------------------------------------------------
; SpellPontori (cleric A): as Repond, against skeletons (shape 19h): once a fight, one time
; in two, kill (each 3 in 4).
;------------------------------------------------------------------------------
SpellPontori:	cmp byte ptr Location, 80h	;@6153
	jne Pontori_Fail	;@6158
	cmp byte ptr FoeTile, 19h	; the monsters' shape: 25 skeleton	;@615A
	jne Pontori_Fail	;@615F
	cmp byte ptr KillSpellUsed, 0	;@6161
	jne Pontori_Fail	;@6166
	mov byte ptr KillSpellUsed, 0FFh	;@6168
	mov al, dl	;@616D
	mov dh, 0FFh	;@616F
	call Random	;@6171
	shl dl, 1	;@6174
	jb Pontori_Fail	;@6176
	mov dl, al	;@6178
	call SpellFlash	;@617A
	mov al, 0FFh	;@617D
	call HitAllMonsters	;@617F
	jmp Cast_Done	;@6182
Pontori_Fail:	jmp Cast_Failed	;@6185
;------------------------------------------------------------------------------
; SpellApparUnem (cleric B): open the chest the party stands on without its trap, 3 times
; in 4. On the surface a chest is map byte 24h-27h; the low bits say what lies under it
; (0 floor 20h, 1 grass, 2 brush, 3 forest). In a dungeon a chest is cell 40h. Then the gold
; and experience message (EQUIP 80D9). No chest: "Not Here!" and "Failed!".
;------------------------------------------------------------------------------
SpellApparUnem:	mov di, bx	; DI = caster	;@6188
	call SpellFlash	;@618A
	mov dh, 0FFh	;@618D
	call Random	;@618F
	and dl, 3	; 1 in 4: failed	;@6192
	je ApparUnem_Fail	;@6195
	mov bx, word ptr PlayerXY	;@6197
	cmp byte ptr Location, 1	;@619B
	je ApparUnem_Dungeon	;@61A0
	call MapCellAddr	;@61A2
	cmp al, 24h	; 24h-27h: a chest (shape 9)	;@61A5
	jb ApparUnem_NotHere	;@61A7
	cmp al, 27h	;@61A9
	ja ApparUnem_NotHere	;@61AB
	and al, 3	; what lies under it	;@61AD
	shl al, 1	;@61AF
	shl al, 1	;@61B1
	jne ApparUnem_Set	;@61B3
	mov al, 20h	; floor	;@61B5
ApparUnem_Set:	mov byte ptr [bx], al	;@61B7
	jmp short ApparUnem_Gold	;@61B9
ApparUnem_Dungeon:	call DungeonCell	;@61BB
	cmp al, 40h	; 40h: a dungeon chest	;@61BE
	jne ApparUnem_NotHere	;@61C0
	mov byte ptr [bx], 0	; an empty cell	;@61C2
ApparUnem_Gold:	call ChestLoot	; find gold (EQUIP 80D9)	;@61C5
	jmp Cast_Done	;@61C8
ApparUnem_Fail:	jmp Cast_Failed	;@61CB
ApparUnem_NotHere:	lea si, TxtNotHere	; "Not Here!"	;@61CE
	call PrintMsg	;@61D2
	mov al, 0FFh	;@61D5
	call Sound	;@61D7
	jmp ApparUnem_Fail	;@61DA
;------------------------------------------------------------------------------
; SpellSanctu (cleric C): heal 10-29 hit points (random 0-19 + 10, made BCD).
;------------------------------------------------------------------------------
SpellSanctu:	mov ch, dl	;@61DC
	mov dh, 14h	;@61DE
	call Random	;@61E0
	mov al, dl	;@61E3
	add al, 0Ah	;@61E5
	aam	;@61E7
	mov cl, 4	;@61E9
	shl ah, cl	;@61EB
	or al, ah	;@61ED
	mov dh, al	;@61EF
	mov dl, ch	;@61F1
	jmp HealPlayer	;@61F3
;------------------------------------------------------------------------------
; SpellLibRec (cleric G): in a dungeon, a random empty cell of the level.
;------------------------------------------------------------------------------
SpellLibRec:	cmp byte ptr Location, 1	;@61F6
	jne LibRec_Fail	;@61FB
	call SpellFlash	;@61FD
	call DungeonTeleport	;@6200
	jmp Cast_Done	;@6203
LibRec_Fail:	jmp Cast_Failed	;@6206
;------------------------------------------------------------------------------
; SpellAlcort (cleric H): "Cure whom?": a poisoned player becomes good, anyone else "Failed!".
; No player chosen: 35 magic points (this spell's cost) are added to the record at BX: the
; caster after Esc or 0 (AskPlayer keeps BX), but an empty slot's record if one was picked.
; The only spell that refunds.
;------------------------------------------------------------------------------
SpellAlcort:	lea si, MsgCureWhom	;@6209
	call PrintMsg	;@620D
	call AskPlayer	;@6210
	je Alcort_Refund	;@6213
	dec al	;@6215
	cmp byte ptr [bx+11h], 50h	; status: 'P' poisoned	;@6217
	jne Alcort_Fail	;@621B
	call FlashPlayer	; FlashPlayer	;@621D
	call SpellFlash	;@6220
	mov byte ptr [bx+11h], 47h	; 'G' good	;@6223
	call FlashPlayer	; FlashPlayer	;@6227
	jmp Cast_Done	;@622A
Alcort_Fail:	jmp Cast_Failed	;@622D
Alcort_Refund:	mov al, 35h	; 35 (BCD): the cost of spell H	;@6230
	add al, byte ptr [bx+19h]	; magic points	;@6232
	daa	;@6235
	mov byte ptr [bx+19h], al	;@6236
	jmp Cast_Done	;@6239
;------------------------------------------------------------------------------
; SpellSequitu (cleric I): leave the dungeon for Sosaria.
;------------------------------------------------------------------------------
SpellSequitu:	cmp byte ptr Location, 1	;@623C
	jne Sequitu_Fail	;@6241
	call SpellFlash	;@6243
	call ExitToSosaria	;@6246
	jmp Cast_Done	;@6249
Sequitu_Fail:	jmp Cast_Failed	;@624C
;------------------------------------------------------------------------------
; SpellSanctuMani (cleric K): heal 20-99 hit points (random 0-79 + 20).
;------------------------------------------------------------------------------
SpellSanctuMani:	mov ch, dl	;@624F
	mov dh, 50h	;@6251
	call Random	;@6253
	mov al, dl	;@6256
	add al, 14h	;@6258
	aam	;@625A
	mov cl, 4	;@625C
	shl ah, cl	;@625E
	or al, ah	;@6260
	mov dh, al	;@6262
	mov dl, ch	;@6264
	jmp HealPlayer	;@6266
;------------------------------------------------------------------------------
; SpellVieda (cleric L): not in a fight: the map view of the Peer at gem command (VIEW
; ShowDungeonMap in a dungeon, ShowGemMap elsewhere).
;------------------------------------------------------------------------------
SpellVieda:	cmp byte ptr Location, 80h	;@6269
	je Vieda_Fail	;@626E
	call SpellFlash	;@6270
	cmp byte ptr Location, 1	;@6273
	jne Vieda_Surface	;@6278
	call ShowDungeonMap	;@627A
	jmp short Vieda_Done	;@627D
Vieda_Surface:	call ShowGemMap	;@627F
Vieda_Done:	jmp Cast_Done	;@6282
Vieda_Fail:	jmp Cast_Failed	;@6285
;------------------------------------------------------------------------------
; SpellSurmandum (cleric N): not in a fight, "Resurect whom?": a dead player becomes good
; 3 times in 4; otherwise ashes, and "Failed!".
;------------------------------------------------------------------------------
SpellSurmandum:	cmp byte ptr Location, 80h	;@6288
	je Surmandum_Fail	;@628D
	lea si, MsgResurectWhom	;@628F
	call PrintMsg	;@6293
	call AskPlayer	;@6296
	je Surmandum_Fail	;@6299
	dec al	;@629B
	cmp byte ptr [bx+11h], 44h	; status: 'D' dead	;@629D
	jne Surmandum_Fail	;@62A1
	call FlashPlayer	; FlashPlayer	;@62A3
	call SpellFlash	;@62A6
	call FlashPlayer	; FlashPlayer	;@62A9
	mov dh, 0FFh	;@62AC
	call Random	;@62AE
	and dl, 3	; 1 in 4: ashes	;@62B1
	je Surmandum_Ashes	;@62B4
	mov byte ptr [bx+11h], 47h	; 'G' good	;@62B6
	jmp Cast_Done	;@62BA
Surmandum_Ashes:	mov byte ptr [bx+11h], 41h	; 'A' ashes	;@62BD
Surmandum_Fail:	jmp Cast_Failed	;@62C1
;------------------------------------------------------------------------------
; SpellAnjuSermani (cleric P): not in a fight, "Recall whom?": a player in ashes becomes
; good, and the caster loses 5 wisdom (BCD, not checked for going below 0).
;------------------------------------------------------------------------------
SpellAnjuSermani:	mov di, bx	; DI = caster	;@62C4
	cmp byte ptr Location, 80h	;@62C6
	je AnjuSermani_Fail	;@62CB
	lea si, MsgRecallWhom	;@62CD
	call PrintMsg	;@62D1
	call AskPlayer	;@62D4
	je AnjuSermani_Fail	;@62D7
	dec al	;@62D9
	cmp byte ptr [bx+11h], 41h	; status: 'A' ashes	;@62DB
	jne AnjuSermani_Fail	;@62DF
	call FlashPlayer	; FlashPlayer	;@62E1
	call SpellFlash	;@62E4
	call FlashPlayer	; FlashPlayer	;@62E7
	mov byte ptr [bx+11h], 47h	; 'G' good	;@62EA
	mov al, byte ptr [di+15h]	; the caster's wisdom	;@62EE
	sub al, 5	;@62F1
	das	;@62F3
	mov byte ptr [di+15h], al	;@62F4
	jmp Cast_Done	;@62F7
AnjuSermani_Fail:	jmp Cast_Failed	;@62FA
CODE ENDS
END
